def cast_value(value, to: str):
    """Convert one value to `int`, `float`, `str` or `bool`; null stays null."""
    if value is None:
        return None
    try:
        if to == "str":
            return _to_str(value)
        if to == "int":
            if isinstance(value, int):
                return int(value)
            if isinstance(value, str) and _INT.fullmatch(value.strip()):
                return int(value.strip())
            number = float(value)
            if number == int(number):
                return int(number)
        elif to == "float":
            number = float(value)
            if math.isfinite(number):
                return number
        elif to == "bool":
            if isinstance(value, bool):
                return value
            text = _to_str(value).strip().lower()
            if text in _TRUE:
                return True
            if text in _FALSE:
                return False
    except (TypeError, ValueError, OverflowError):
        pass
    raise PlanError("type_error", f"cannot cast {type_name(value)} {value!r} to {to}")

def _join(step, columns, schemas):
    right_name = step["right"]
    if right_name not in schemas:
        raise unknown("table", right_name, schemas)
    right_columns = schemas[right_name]

    if "on" in step:
        if "left_on" in step or "right_on" in step:
            raise PlanError("invalid_plan", "give either `on` or `left_on` with `right_on`, not both")
        left_keys = right_keys = step["on"]
    elif "left_on" in step and "right_on" in step:
        left_keys, right_keys = step["left_on"], step["right_on"]
        if len(left_keys) != len(right_keys):
            raise PlanError("invalid_plan", "`left_on` and `right_on` must list the same number of columns")
    else:
        raise PlanError("missing_field", "join needs `on`, or `left_on` with `right_on`")
    _need(left_keys, columns)
    _need(right_keys, right_columns)

    suffix = step.get("right_suffix", "_right")
    carried = {c: (c + suffix if c in columns else c) for c in right_columns if c not in right_keys}
    out = [*columns, *carried.values()]
    _unique(out)
    keep_unmatched = step.get("how", "inner") == "left"
    blank = dict.fromkeys(carried.values())

    def run(rows, tables):
        right_rows = tables[right_name]
        readers = [
            _key_readers([row[l] for row in rows], [row[r] for row in right_rows])
            for l, r in zip(left_keys, right_keys)
        ]
        index = defaultdict(list)
        for row in right_rows:
            if all(row[k] is not None for k in right_keys):
                index[tuple(read(row[k]) for k, (_, read) in zip(right_keys, readers))].append(row)
        result = []
        for row in rows:
            matches = ()
            if all(row[k] is not None for k in left_keys):
                matches = index.get(tuple(read(row[k]) for k, (read, _) in zip(left_keys, readers)), ())
            for match in matches:
                result.append({**row, **{new: match[old] for old, new in carried.items()}})
            if not matches and keep_unmatched:
                result.append({**row, **blank})
        return result

    return out, run

async function checkConfiguration(): Promise<HealthCheckResult[]> {
  const results: HealthCheckResult[] = [];

  try {
    const config = loadConfig();

    // Check if config file exists
    const configPath = path.join(process.cwd(), '.dhruv-config.json');
    if (fs.existsSync(configPath)) {
      results.push({
        category: 'Configuration',
        status: 'pass',
        message: 'Configuration file found and loaded successfully'
      });
    } else {
      results.push({
        category: 'Configuration',
        status: 'warn',
        message: 'No configuration file found',
        recommendation: 'Run "dhruv init" to create a configuration file'
      });
    }

    // Check model configuration
    if (config.model && config.model.trim().length > 0) {
      results.push({
        category: 'Configuration',
        status: 'pass',
        message: `Model configured: ${config.model}`
      });
    } else {
      results.push({
        category: 'Configuration',
        status: 'fail',
        message: 'No model configured',
        recommendation: 'Set a model using "dhruv init" or --model flag'
      });
    }

    // Check theme configuration
    if (config.theme && ['default', 'dark', 'light', 'mono'].includes(config.theme)) {
      results.push({
        category: 'Configuration',
        status: 'pass',
        message: `Theme configured: ${config.theme}`
      });
    } else {
      results.push({
        category: 'Configuration',
        status: 'warn',
        message: 'Invalid or missing theme configuration',
        recommendation: 'Set theme using "dhruv init"'
      });
    }

  } catch (error) {
    results.push({
      category: 'Configuration',
      status: 'fail',
      message: `Configuration check failed: ${(error as Error).message}`,
      details: error
    });
  }

  return results;
}

export function ingestCommittedRange(range: ResolvedRange, selection: Partial<RangeSelection> = {}): CommittedRangeOutcome {
  const { root, base, mergeBase, head } = range;
  const limits = { ...DEFAULT_RANGE_LIMITS, ...selection };
  const selected = pathSelector(selection.include ?? ['**'], selection.exclude ?? []);

  const diffFlags = ['--no-ext-diff', '--no-textconv', '--no-color', '-M'];
  const raw = git(root, ['diff', '--raw', '-z', ...diffFlags, mergeBase, head, '--']);
  if (raw.status !== 0) return failure('git-error', 'Git could not list the changed files.');
  const entries = parseRaw(raw.stdout);

  const files: RangeFile[] = [];
  const exclusions: RangeExclusion[] = [];
  let considered = 0;
  let totalBytes = PROMPT_OVERHEAD_BYTES;
  const exclude = (path: string, reason: ExclusionReason) => exclusions.push({ path, reason });

  entries.forEach((entry) => {
    if (!selected(entry.path)) return exclude(entry.path, 'ignored');
    const position = considered++;
    if (entry.status === 'deleted') return exclude(entry.path, 'deleted');
    if (!CODE_FILE.test(entry.path)) return exclude(entry.path, 'unsupported');
    if (position >= limits.maxChangedFiles) return exclude(entry.path, 'file-limit');

    const paths = entry.oldPath ? [entry.oldPath, entry.path] : [entry.path];
    const diff = git(root, ['diff', `--unified=${RANGE_CONTEXT_LINES}`, ...diffFlags, mergeBase, head, '--', ...paths]);
    if (diff.status !== 0) return exclude(entry.path, 'unreadable');
    if (/^Binary files /m.test(diff.stdout) || /^GIT binary patch/m.test(diff.stdout)) return exclude(entry.path, 'binary');

    const start = diff.stdout.search(/^@@ /m);
    const full = start === -1 ? '' : diff.stdout.slice(start);
    if (parseChangedLines(full).length === 0) return exclude(entry.path, 'no-line-changes');

    const file = { path: entry.path, oldPath: entry.oldPath, status: entry.status };
    const patch = fitHunks(full, file, limits.maxFileBytes);
    const changedLines = parseChangedLines(patch);
    if (changedLines.length === 0) return exclude(entry.path, 'oversized');
    const selectedFile = { ...file, changedLines, patch };
    const bytes = Buffer.byteLength(filePromptSection(selectedFile)) + (files.length > 0 ? PROMPT_SEPARATOR_BYTES : 0);
    if (totalBytes + bytes > limits.maxTotalBytes) return exclude(entry.path, 'total-limit');
    totalBytes += bytes;
    files.push(selectedFile);
    if (patch.length < full.length) exclude(entry.path, 'truncated');
  });

  const byReason = Object.fromEntries(EXCLUSION_REASONS.map((reason) => [reason, 0])) as Record<ExclusionReason, number>;
  for (const { reason } of exclusions) byReason[reason]++;

  return {
    ok: true,
    base,
    mergeBase,
    head,
    files,
    exclusions,
    coverage: {
      changedFiles: entries.length,
      analyzedFiles: files.length,
      skippedFiles: exclusions.length - byReason.truncated,
      truncatedFiles: byReason.truncated,
      complete: !COVERAGE_BREAKING.some((reason) => byReason[reason] > 0),
      byReason,
    },
  };
}
